private static boolean deleteFromPatternToSetMap(final Map<Patterns, ?> map, final Patterns pattern, final Object setElement) {
    boolean deleted = false;
    Set<?> set = (Set<?>) map.get(pattern);
    if (set != null) {
        deleted = set.remove(setElement);
        if (set.isEmpty()) {
            map.remove(pattern);
        }
    }
    return deleted;
}
